using Microsoft.EntityFrameworkCore;
public sealed record OrderSummary(int Id, string Customer, decimal Total, int Payments);
public sealed record LineDto(string Product, int Quantity);
public sealed record PaymentDto(decimal Amount, DateTime PaidAt);
public sealed record OrderDetails(
    int Id, string Customer, List<LineDto> Lines, List<PaymentDto> Payments);
public class Customer
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
}
public class Product
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public string Description { get; set; } = "";
}
public class OrderLine
{
    public int Id { get; set; }
    public int OrderId { get; set; }
    public int ProductId { get; set; }
    public Product Product { get; set; } = null!;
    public int Quantity { get; set; }
    public decimal UnitPrice { get; set; }
}
public class Payment
{
    public int Id { get; set; }
    public int OrderId { get; set; }
    public decimal Amount { get; set; }
    public DateTime PaidAt { get; set; }
}
public class Order
{
    public int Id { get; set; }
    public int CustomerId { get; set; }
    public Customer Customer { get; set; } = null!;
    public DateTime PlacedAt { get; set; }
    public List<OrderLine> Lines { get; set; } = [];
    public List<Payment> Payments { get; set; } = [];
}
public sealed class ShopDb(DbContextOptions<ShopDb> options) : DbContext(options)
{
    public DbSet<Order> Orders => Set<Order>();
}
